void sub_020053A8(u8 playerID, BOOL paused);

void sub_020053A8(u8 playerID, BOOL paused) {
    u8 handleType;
    u8 *playerPaused;

    if (playerID == PLAYER_FIELD) {
        playerPaused = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_FIELD_BGM_PAUSED);
        handleType = SOUND_HANDLE_TYPE_FIELD_BGM;
    } else if (playerID == PLAYER_BGM) {
        playerPaused = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_BGM_PAUSED);
        handleType = SOUND_HANDLE_TYPE_BGM;
    } else {
        return;
    }

    if (paused == FALSE) {
        sub_02004A60((u16)GF_NNS_SndPlayerGetSeqNo(GF_GetSoundHandle(handleType)));
    }

    NNS_SndPlayerPause(GF_GetSoundHandle(handleType), paused);
    *playerPaused = paused;
}
